/// <summary>
/// Event handler class for TAMRebateDealGUPExtensionHelper
/// </summary>
internal final class METTAMRebateDealGUPExtensionHelperEventHandler
{
}

Method.Source:
/// <summary>
/// Post event handler for setUpGUPUIForRebateDealFormDetailPage
/// </summary>
/// <param name="args">XppPrePostArgs</param>
[PostHandlerFor(classStr(TAMRebateDealGUPExtensionHelper), staticMethodStr(TAMRebateDealGUPExtensionHelper, setUpGUPUIForRebateDealFormDetailPage))]
public static void TAMRebateDealGUPExtensionHelper_Post_setUpGUPUIForRebateDealFormDetailPage(XppPrePostArgs args)
{
    FormRun formRun = args.getArg(identifierStr(_formRun));
    FormDataSource fdsDeal = formRun.dataSource(formDataSourceStr(TAMRebateDeal,TAMRebateDeal));
    TAMRebateDeal rebateDeal = fdsDeal.cursor();

    if (rebateDeal.METVolumetricTierDeal)
    {
        formRun.design().controlName(formControlStr(TAMRebateDeal, SetupHeaderView_RebateOutputType)).allowEdit(false);
    }
    else
    {
        formRun.design().controlName(formControlStr(TAMRebateDeal, SetupHeaderView_RebateOutputType)).allowEdit(true);
    }

    if (formRun.args().menuItemName() == menuitemdisplaystr(TAMRebateDealListPageVendRebate))
    {
        formRun.design().controlName(formControlStr(TAMRebateDeal, TableGrid_AccountCode)).visible(false);
        formRun.design().controlName(formControlStr(TAMRebateDeal, TableGrid_AccountRelation)).visible(false);
        formRun.design().controlName(formControlStr(TAMRebateDeal, TableGrid_ItemCode)).visible(false);
        formRun.design().controlName(formControlStr(TAMRebateDeal, TableGrid_ItemRelation)).visible(false);
    }
}
